import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.yse_Y9k2.js";const m=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"notion-seed","text":"L'addition avant l'écriture.","tagline":"Déclarez vos bases Notion en YAML. Avant toute écriture, voyez — en nombre de lignes — ce que chaque changement coûtera à vos données.","actions":[{"theme":"brand","text":"Commencer","link":"/fr/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/tykok/notion-seed"}]},"features":[{"title":"Chiffré avant d'écrire","details":"Chaque ligne du plan dit combien de lignes perdront leur valeur — et combien en recevront une plausible et fausse."},{"title":"Détection de dérive","details":"Le state distingue « le YAML a changé » de « quelqu'un a modifié Notion à la main », et montre le second avant le plan."},{"title":"Un garde-fou CI à votre main","details":"plan --fail-on=<classes> arrête le workflow sur les changements que vous nommez, et rien d'autre."},{"title":"Aucun refus de principe","details":"Il informe, vous décidez. Seul ce que l'API ne sait pas exprimer est retenu — avec la marche à suivre à la main."}]},"headers":[],"relativePath":"fr/index.md","filePath":"fr/index.md"}`),o={name:"fr/index.md"};function i(r,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h2 id="pourquoi" tabindex="-1">Pourquoi <a class="header-anchor" href="#pourquoi" aria-label="Permalink to &quot;Pourquoi&quot;">​</a></h2><p>Notion finit par faire tourner le quotidien : projets, tâches, docs, rituels. Gérer un espace à la main est déjà compliqué. Gérer ses bases l&#39;est encore plus — une option renommée, un statut retiré, et des lignes changent de valeur sans bruit. notion-seed est un petit outil né de là.</p><p>Déclarer un workspace Notion en fichiers n&#39;est pas le problème difficile. Le problème difficile, c&#39;est de savoir ce que l&#39;API va faire de vos données quand la déclaration change.</p><p>Six comportements mesurés contre l&#39;API, qu&#39;un outil qui se contente d&#39;envoyer la requête ne vous signale pas :</p><table tabindex="0"><thead><tr><th>Changement</th><th>Ce que fait l&#39;API</th></tr></thead><tbody><tr><td>Renommer une option (avec son id)</td><td>Répond <code>200</code>, ne change rien</td></tr><tr><td>Retirer une option de <code>select</code></td><td>Les lignes concernées passent à vide</td></tr><tr><td>Retirer une option de <code>multi_select</code></td><td>Les lignes concernées perdent <strong>cette valeur</strong> — elles ne passent à vide que si elles n&#39;en portaient pas d&#39;autre</td></tr><tr><td>Retirer une option de <code>status</code></td><td><strong>Réassigne les lignes à une autre option</strong>, sans erreur</td></tr><tr><td><code>multi_select</code> → <code>select</code></td><td><strong>Ne garde qu&#39;une valeur</strong> sur les lignes qui en portaient plusieurs</td></tr><tr><td><code>select</code> → <code>multi_select</code></td><td>Recrée les options : une ligne ne garde sa valeur que si le YAML redéclare une option <strong>de même nom</strong> ; les autres passent à vide</td></tr></tbody></table><p>Mesurés le 2026-09-24 contre l&#39;API <code>2025-09-03</code>, sur des lignes remplies — le dernier le 2026-09-25.</p><p>Le retrait d&#39;option de <code>status</code> et <code>multi_select</code> → <code>select</code> sont ceux qui justifient l&#39;outil : la donnée n&#39;est pas perdue, elle est remplacée par une valeur plausible et fausse, indistinguable après coup.</p><p><code>notion-seed</code> ne vous en empêche pas. Il vous dit, <strong>avant d&#39;écrire</strong>, combien de lignes sont concernées. Une option de <code>status</code> retirée du YAML, deux lignes la portent :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ntn 0.22.11 — workspace Example Space (33333333-3333-4333-8333-333333333333)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Plan: 0 to add, 1 to change, 0 to destroy</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ~ database.tasks  [silent rewrite]</span></span>
<span class="line"><span>      - option &quot;Fait&quot; (property &quot;Statut&quot;) — absent from the YAML: the API replaces the whole list of options  [silent rewrite]</span></span>
<span class="line"><span>          → 2 rows will be reassigned to another option, without a trace.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Impact: 2 values reassigned without a trace.</span></span></code></pre></div><p>Le chiffre est mesuré, pas déduit : la même ligne serait classée <code>safe</code>, avec <code>0 rows affected</code>, si personne n&#39;utilisait cette option. C&#39;est ce qu&#39;un refus par principe ne savait pas voir, et pourquoi il a été remplacé par une mesure. Ce qui n&#39;a pas pu être compté — hors ligne, ou quand la requête échoue — ressort en <code>unknown impact</code>, jamais en « rien à perdre ».</p><div class="tip custom-block"><p class="custom-block-title">Vous restez aux commandes</p><p>Vous êtes responsable de votre base. notion-seed est responsable de ce que vous savez au moment d&#39;appuyer sur entrée. En CI, <a href="/notion-seed/fr/commands#en-ci"><code>--fail-on</code></a> confie la décision au workflow.</p></div><h2 id="ce-que-l-api-ne-sait-pas-faire" tabindex="-1">Ce que l&#39;API ne sait pas faire <a class="header-anchor" href="#ce-que-l-api-ne-sait-pas-faire" aria-label="Permalink to &quot;Ce que l&#39;API ne sait pas faire&quot;">​</a></h2><p>Deux changements sont inexprimables, mesurés le 2026-09-24 :</p><table tabindex="0"><thead><tr><th>Changement</th><th>Ce que fait l&#39;API</th></tr></thead><tbody><tr><td>Renommer une option</td><td>Répond <code>200</code>, ne change rien</td></tr><tr><td>Changer la couleur d&#39;une option</td><td>Répond <code>400</code>, que l&#39;option soit désignée par son id ou par son nom, et tout le PATCH de la propriété échoue</td></tr></tbody></table><p><code>notion-seed</code> ne les écrit donc pas, et retient la database entière tant qu&#39;ils sont déclarés. Les autres databases du plan s&#39;appliquent. Voir <a href="/notion-seed/fr/commands#ce-qu-il-retient">Ce qu&#39;il retient</a> pour la marche à suivre et le nombre de lignes qu&#39;elle nomme.</p><h2 id="etat-actuel" tabindex="-1">État actuel <a class="header-anchor" href="#etat-actuel" aria-label="Permalink to &quot;État actuel&quot;">​</a></h2><p><code>apply</code> crée les databases déclarées et absentes de Notion, modifie celles qui existent déjà — nom, description, icône et propriétés déclarées — et met à la corbeille celles que le YAML ne déclare plus. Le state est mis à jour après chaque ressource écrite. Deux changements d&#39;option, que l&#39;API ne sait pas exprimer, sont retenus avec la migration à faire à la main, et <code>apply</code> sort en code non nul tant qu&#39;ils restent — voir <a href="#ce-que-l-api-ne-sait-pas-faire">Ce que l&#39;API ne sait pas faire</a>.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>init</code>, <code>version</code>, <code>plan</code>, <code>diff</code>, <code>import</code></td><td>disponibles</td></tr><tr><td><code>apply</code></td><td>créations, modifications et destructions — voir <a href="/notion-seed/fr/commands#apply">Appliquer</a></td></tr><tr><td>fichier de state</td><td><code>notion-seed.state.json</code>, écrit par <code>import</code> et <code>apply</code></td></tr><tr><td><code>lifecycle.prevent_destroy</code> / <code>allow_data_loss</code></td><td>accusés de lecture — voir <a href="/notion-seed/fr/yaml#lifecycle-des-accuses-de-lecture">lifecycle</a></td></tr><tr><td><code>--fail-on</code></td><td>le garde-fou de CI — voir <a href="/notion-seed/fr/commands#en-ci">En CI</a></td></tr></tbody></table>`,18)])])}const h=t(o,[["render",i]]);export{m as __pageData,h as default};
